code3='''def transform(grid):
    from collections import defaultdict
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if all(v == 8 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    rb, cb = [-1] + sep_rows + [h], [-1] + sep_cols + [w]
    rows = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    cols = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]
    points = {2: [], 3: []}
    for ri, (r0, r1) in enumerate(rows):
        for ci, (c0, c1) in enumerate(cols):
            for color in points:
                if any(grid[r][c] == color for r in range(r0, r1) for c in range(c0, c1)):
                    points[color].append((ri, ci))
    lines = {color: set() for color in points}
    for color, pts in points.items():
        by_row, by_col = defaultdict(list), defaultdict(list)
        for ri, ci in pts:
            by_row[ri].append(ci)
            by_col[ci].append(ri)
        for ri, cis in by_row.items():
            if len(cis) >= 2:
                lines[color].update((ri, ci) for ci in range(min(cis), max(cis) + 1))
        for ci, ris in by_col.items():
            if len(ris) >= 2:
                lines[color].update((ri, ci) for ri in range(min(ris), max(ris) + 1))
    out = [row[:] for row in grid]
    for ri, (r0, r1) in enumerate(rows):
        for ci, (c0, c1) in enumerate(cols):
            has2, has3 = (ri, ci) in lines[2], (ri, ci) in lines[3]
            fill = 6 if has2 and has3 else 2 if has2 else 3 if has3 else 0
            if fill:
                for r in range(r0, r1):
                    for c in range(c0, c1):
                        out[r][c] = fill
    return out
